for idx, inp, outp in changed:
    print(f"  {idx}: '{inp}' -> '{outp}'")

# Step 2: For each changed pair, find minimal edit
print("\nAnalyzing minimal edits:")
for idx, inp, outp in changed:
    print(f"Pair {idx}: '{inp}' -> '{outp}'")

    # Find what changes at each position
    min_len = min(len(inp), len(outp))
    for i in range(min_len):
        if inp[i] != outp[i]:
            print(f"  Position {i}: '{inp[i]}' -> '{outp[i]}'")

    if len(inp) != len(outp):
        print(f"  Length change: {len(inp)} -> {len(outp)}")

    # Look for substring patterns
    if len(inp) > 1 and len(outp) > 1:
        # Try to find longer patterns that might be replaced
        for length in range(2, min(len(inp), len(outp)) + 1):
            for i in range(len(inp) - length + 1):
                substr = inp[i:i+length]
                if substr in outp:
                    # Find where it maps to
                    pos = outp.find(substr)
                    if pos != -1:
                        # Check if this is a consistent mapping
                        end_pos = pos + length
                        if end_pos <= len(outp):
                            mapped = outp[pos:end_pos]
                            print(f"  Substring '{substr}' -> '{mapped}' at position {i}")

